class SoundSystem{constructor(){this.sounds={};this.muted=localStorage.getItem('soundMuted')==='true';this.volume=parseFloat(localStorage.getItem('soundVolume')|| '0.3');this.initialized=false;}init(){if(this.initialized)return;this.soundDefinitions={like:{type:'beep',frequency:800,duration:100},save:{type:'beep',frequency:1200,duration:150},next:{type:'beep',frequency:600,duration:80},levelUp:{type:'beep',frequency:1500,duration:300},streak:{type:'beep',frequency:1000,duration:200},achievement:{type:'beep',frequency:1400,duration:250},error:{type:'beep',frequency:200,duration:150}};this.initialized=true;console.log('🔊 Sound system initialized');}play(soundName){if(this.muted || !this.initialized)return;const soundDef=this.soundDefinitions[soundName];if(!soundDef){console.warn(`Sound "${soundName}" not found`);return;}try{if(!this.audioContext){this.audioContext=new(window.AudioContext || window.webkitAudioContext)();}const ctx=this.audioContext;const oscillator=ctx.createOscillator();const gainNode=ctx.createGain();oscillator.connect(gainNode);gainNode.connect(ctx.destination);oscillator.frequency.value=soundDef.frequency;oscillator.type='sine';const now=ctx.currentTime;gainNode.gain.setValueAtTime(0,now);gainNode.gain.linearRampToValueAtTime(this.volume,now + 0.01);gainNode.gain.exponentialRampToValueAtTime(0.01,now + soundDef.duration / 1000);oscillator.start(now);oscillator.stop(now + soundDef.duration / 1000);}catch(error){console.error('Error playing sound:',error);}}toggleMute(){this.muted=!this.muted;localStorage.setItem('soundMuted',this.muted);console.log(`🔊 Sound ${this.muted ? 'muted':'unmuted'}`);return this.muted;}setVolume(volume){this.volume=Math.max(0,Math.min(1,volume));localStorage.setItem('soundVolume',this.volume);}isMuted(){return this.muted;}}window.soundSystem=new SoundSystem();document.addEventListener('click',()=>{if(!window.soundSystem.initialized){window.soundSystem.init();}},{once:true});console.log('🎵 Sound system loaded and ready');